// The orb's three pictures as data URLs (generated from orb-picture.jpg, orb-galaxy.jpg, orb-glass.png).
// Connect's page is a local file, and WebGL may not read pictures loaded from local files; data URLs it may.
window.MERIDIAN_ORB_PICTURES = {
  picture: 'data:image/jpeg;base64,',
  galaxy: 'data:image/jpeg;base64,',
  glass: 'data:image/png;base64,'
};
